import json,csv,collections,re
O={};L=[]
for l in open('shopify/orders.jsonl'):
    d=json.loads(l)
    if '__parentId' in d: L.append(d)
    else: O[d['id']]=d
print(len(O),len({o['name'] for o in O.values()}),len(L),len({l['id'] for l in L}))
print(collections.Counter(bool(l['variant']) for l in L), sum(1 for l in L if l['__parentId'] not in O))
print(sum(1 for o in O.values() if not o['customer']), collections.Counter(type(o['customer']).__name__ for o in O.values()))
cu=collections.defaultdict(set)
for o in O.values():
    c=o['customer']
    if c: cu[c['id']].add((c['email'] or '').lower())
print(len(cu), sum(1 for v in cu.values() if len(v)>1))
names={o['name'] for o in O.values()}
ob=list(csv.DictReader(open('3pl/outbound.csv')))
print(sum(1 for r in ob if r['Order Reference'].startswith('#') and r['Order Reference'] not in names))
print(sum(1 for o in O.values() if not o['name'].startswith('#')), [o['name'] for o in O.values()][:3])
print(len([k for k in O if not re.fullmatch(r'gid://shopify/Order/\d+',k)]))
# line variants vs products
prod=[json.loads(l) for l in open('shopify/products.jsonl')]
pv={p['id'] for p in prod if 'sku' in p}
print(sum(1 for l in L if l['variant'] and l['variant']['id'] not in pv), [l for l in L if not l['variant']][:2])
# emails
em=collections.defaultdict(set)
for cid,v in cu.items():
    for e in v: em[e].add(cid)
print(sum(1 for e,s in em.items() if len(s)>1))
def norm(e):
    u,d=e.split('@');u=u.split('+')[0]
    if d in('gmail.com','googlemail.com'):u=u.replace('.','')
    return u+'@'+d
nm=collections.defaultdict(set)
for cid,v in cu.items():
    for e in v: nm[norm(e)].add(cid)
print(sum(1 for e,s in nm.items() if len(s)>1), collections.Counter(len(s) for s in nm.values()))
print(collections.Counter(e.split('@')[1] for e in em).most_common(8))
